SELECT CASE WHEN c.credit_limit >= 14300 THEN 'high' WHEN c.credit_limit >= 6900 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, DATE_FORMAT(c.signup_date, 'yyyy-MM') AS signup_month, SORT_ARRAY(COLLECT_SET(we.event_type)) AS event_type_list, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(we.page))) AS page_values FROM web_events we INNER JOIN sessions s ON we.session_id = s.id RIGHT OUTER JOIN customers c ON s.customer_id = c.id GROUP BY CASE WHEN c.credit_limit >= 14300 THEN 'high' WHEN c.credit_limit >= 6900 THEN 'mid' ELSE 'low' END, DATE_FORMAT(c.signup_date, 'yyyy-MM');
